-- REFERENCE OUTLINE ONLY.
create table if not exists public.creator_memory_deposits (id uuid primary key default gen_random_uuid(), trust_id uuid not null, source_type text not null, source_id uuid not null, depositor_authority_id uuid not null, purposes jsonb not null, access_class text not null, restrictions jsonb not null default '{}'::jsonb, state text not null default 'draft', source_manifest_id uuid not null, idempotency_key text not null unique, created_at timestamptz not null default now());
create table if not exists public.creator_memory_custodians (id uuid primary key default gen_random_uuid(), trust_id uuid not null, legal_name text not null, jurisdiction text not null, qualification_state text not null default 'under_review', independence_evidence jsonb not null default '{}'::jsonb, last_restore_test_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.creator_memory_preservation_packages (id uuid primary key default gen_random_uuid(), deposit_id uuid not null references public.creator_memory_deposits(id), profile_version text not null, package_manifest jsonb not null, manifest_digest text not null, state text not null default 'draft', created_at timestamptz not null default now());
create table if not exists public.creator_memory_package_custody (id uuid primary key default gen_random_uuid(), package_id uuid not null references public.creator_memory_preservation_packages(id), custodian_id uuid not null references public.creator_memory_custodians(id), custody_state text not null default 'proposed', accepted_manifest_digest text, accepted_at timestamptz, created_at timestamptz not null default now(), unique(package_id,custodian_id));
alter table public.creator_memory_deposits enable row level security; alter table public.creator_memory_custodians enable row level security; alter table public.creator_memory_preservation_packages enable row level security; alter table public.creator_memory_package_custody enable row level security;
